var repeatLookupCache = {};

function soulzQueryParam(url, key) {
  try {
    var m = String(url || "").match(new RegExp("[?&]" + key + "=([^&]*)"));
    return m ? decodeURIComponent(m[1]) : "";
  } catch (e) { return ""; }
}

function soulzHtmlText(raw) {
  var s = String(raw || "");
  s = s.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ");
  s = s.replace(/<br\s*\/?>/gi, " ").replace(/<\/(?:p|div|li|tr|td|th|h[1-6])>/gi, " ");
  s = s.replace(/<[^>]+>/g, " ");
  s = s.replace(/&nbsp;|&#160;/gi, " ").replace(/&amp;/gi, "&").replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'");
  s = s.replace(/&#x([0-9a-f]+);/gi, function(_, h){ try { return String.fromCharCode(parseInt(h, 16)); } catch(e){ return " "; } });
  s = s.replace(/&#(\d+);/g, function(_, d){ try { return String.fromCharCode(parseInt(d, 10)); } catch(e){ return " "; } });
  var fw = {"０":"0","１":"1","２":"2","３":"3","４":"4","５":"5","６":"6","７":"7","８":"8","９":"9","．":".","：":":"};
  s = s.split("").map(function(c){ return fw[c] !== undefined ? fw[c] : c; }).join("");
  return s.replace(/\s+/g, " ").trim();
}

function soulzRepeatCandidates(raw) {
  var s = soulzHtmlText(raw);
  var vals = [];
  function add(v, unit) {
    var n = parseFloat(v);
    if (!isFinite(n)) return;
    if ((unit || "").toLowerCase() === "mm") n = n / 10;
    if (n > 0 && n <= 200) vals.push(Math.round(n * 100) / 100);
  }
  var regs = [
    /リピート[^0-9]{0,80}(?:タテ|縦)\s*[:：]?\s*(\d{1,3}(?:\.\d{1,2})?)\s*(cm|㎝|mm)?/gi,
    /(?:柄\s*)?リピート[^0-9]{0,50}(\d{1,3}(?:\.\d{1,2})?)\s*(cm|㎝|mm)/gi,
    /(?:タテ|縦)\s*[:：]?\s*(\d{1,3}(?:\.\d{1,2})?)\s*(cm|㎝|mm)[^。]{0,60}リピート/gi
  ];
  regs.forEach(function(re) {
    var m, guard = 0;
    while ((m = re.exec(s)) && guard++ < 30) add(m[1], m[2] || "cm");
  });
  if (!vals.length) return [];
  var counts = {};
  vals.forEach(function(v){ var k = v.toFixed(2); counts[k] = (counts[k] || 0) + 1; });
  return Object.keys(counts).map(function(k){ return {value: Number(k), count: counts[k]}; })
    .sort(function(a,b){ return b.count - a.count || vals.indexOf(a.value) - vals.indexOf(b.value); });
}

async function soulzLoadText(url) {
  var req = new Request(url);
  req.headers = {
    "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 Version/18.0 Mobile/15E148 Safari/604.1",
    "Accept-Language": "ja-JP,ja;q=0.9,en;q=0.5"
  };
  return await req.loadString();
}

async function soulzFindRepeat(code) {
  code = String(code || "").toUpperCase().replace(/\s+/g, "").replace(/[^A-Z0-9\-]/g, "");
  if (!code) return {ok:false, code:code};

  if (repeatLookupCache[code]) return repeatLookupCache[code];

  // Sangetsu product detail URLs are predictable for many wallpaper product codes.
  var officialUrl = "https://www.sangetsu.co.jp/product/detail/" + encodeURIComponent(code) + "/";
  try {
    var rawOfficial = await soulzLoadText(officialUrl);
    var textOfficial = soulzHtmlText(rawOfficial).toUpperCase();
    var officialCandidates = soulzRepeatCandidates(rawOfficial);
    if (textOfficial.indexOf(code) >= 0 && officialCandidates.length) {
      var officialResult = {ok:true, code:code, repeatCm:officialCandidates[0].value, sourceName:"サンゲツ", sourceUrl:officialUrl, confidence:"official"};
      repeatLookupCache[code] = officialResult;
      return officialResult;
    }
  } catch (e) {}

  var q = '"' + code + '" 壁紙 リピート タテ cm';
  var searches = [
    {name:"Bing", url:"https://www.bing.com/search?q=" + encodeURIComponent(q) + "&setlang=ja-jp"},
    {name:"DuckDuckGo", url:"https://html.duckduckgo.com/html/?q=" + encodeURIComponent(q)}
  ];
  for (var i=0;i<searches.length;i++) {
    try {
      var raw = await soulzLoadText(searches[i].url);
      var upper = soulzHtmlText(raw).toUpperCase();
      var cands = soulzRepeatCandidates(raw);
      if (upper.indexOf(code) >= 0 && cands.length) {
        var result = {ok:true, code:code, repeatCm:cands[0].value, sourceName:searches[i].name+"検索", sourceUrl:searches[i].url, confidence:"search"};
        repeatLookupCache[code] = result;
        return result;
      }
    } catch (e) {}
  }

  var none = {ok:false, code:code, sourceName:"ネット検索", sourceUrl:"https://www.google.com/search?q="+encodeURIComponent(q)};
  repeatLookupCache[code] = none;
  return none;
}

async function soulzDeliverRepeatResult(params) {
  var result;
  try { result = await soulzFindRepeat(params.code); }
  catch (e) { result = {ok:false, code:params.code, error:String(e)}; }
  result.roomId = params.roomId || "";
  result.category = params.category || "";
  result.token = params.token || "";
  try {
    await web.evaluateJavaScript("window.__soulzRepeatSearchResult(" + JSON.stringify(result).replace(/</g, "\\u003c") + ");", false);
  } catch (e) {
    console.log("SOULZ repeat result delivery error: " + e);
  }
}

var web = new WebView();
web.shouldAllowRequest = function(request) {
  var url = request.url || "";
  var draftPrefix = "soulz-save://draft?data=";
  var historyPrefix = "soulz-save://history?data=";
  var prefix = null;
  var path = null;

  if (url.indexOf("soulz-action://settings") === 0) {
    try {
      Safari.open(settingsURL);
    } catch (e) {
      console.log("SOULZ settings error: " + e);
    }
    return false;
  }

  if (url.indexOf("soulz-action://open?") === 0) {
    try {
      var targetURL = soulzQueryParam(url, "url");
      if (targetURL) Safari.open(targetURL);
    } catch (e) {
      console.log("SOULZ open URL error: " + e);
    }
    return false;
  }

  if (url.indexOf("soulz-share://summary?") === 0) {
    try {
      var shareText = soulzQueryParam(url, "text");
      if (shareText) ShareSheet.present([shareText]);
    } catch (e) {
      console.log("SOULZ share error: " + e);
    }
    return false;
  }

  if (url.indexOf("soulz-repeat://search?") === 0) {
    var repeatParams = {
      code: soulzQueryParam(url, "code"),
      roomId: soulzQueryParam(url, "room"),
      category: soulzQueryParam(url, "cat"),
      token: soulzQueryParam(url, "token")
    };
    soulzDeliverRepeatResult(repeatParams);
    return false;
  }

  if (url.indexOf(draftPrefix) === 0) {
    prefix = draftPrefix;
    path = draftPath;
  } else if (url.indexOf(historyPrefix) === 0) {
    prefix = historyPrefix;
    path = historyPath;
  }

  if (prefix !== null) {
    try {
      var payload = url.substring(prefix.length);
      var marker = payload.indexOf("&x=");
      if (marker >= 0) payload = payload.substring(0, marker);
      saveJSON(path, decodeURIComponent(payload));
    } catch (e) {
      console.log("SOULZ bridge error: " + e);
    }
    return false;
  }
  return true;
};

await web.loadHTML(html, "https://soulz.local/");
await web.present(true);
Script.complete();
